    12→  const [isOffline, setIsOffline] = useAtom(NetworkAtoms.isOffline);
    13→
    14→  useEffect(() => {
    15→    const evaluateConnection = (state: {
    16→      isConnected: boolean | null;
    17→      isInternetReachable: boolean | null;
    18→    }) => {
    19→      const nextIsOffline =
    20→        state.isConnected === false || state.isInternetReachable === false;
    21→
    22→      setIsOffline(nextIsOffline);
    23→    };
    24→
    25→    const unsubscribe = NetInfo.addEventListener(evaluateConnection);
    26→
    27→    NetInfo.fetch().then(evaluateConnection).catch(console.warn);
    28→
